function cmPage(html, bridge) {
    var text = String(html).trim();
    var match = text.match(/var pageData=(\{[\s\S]*?\}),pageConfig=/);
    if (!match && text.charAt(0) != '{') throw new Error('Missing page data');
    var data = JSON.parse(match ? match[1] : text);
    if (data.wpnrt) {
        var alphabet = 'ABCDEFGHIJKLMabcdefghijklmNOPQRSTUVWXYZnopqrstuvwxyz0123456789+/=';
        var standard = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/=';
        var encoded = String(data.wpnrt).split('').map(function(c) { return standard.charAt(alphabet.indexOf(c)); }).join('');
        data = JSON.parse(String(bridge.base64Decode(encoded)));
    }
    return data;
}
function cmPart(data, plugin) {
    for (var key in data) if (data[key].pluginCode == plugin && data[key].data && Object.keys(data[key].data).length) return data[key].data;
    return {};
}
function cmUrl(url) { return /^https?:/.test(url) ? url : 'https://n.cmread.com'+url; }

